OutputHTML <p> Demo vx-panel header <p>This is the panel content.</p> <p>             The header and footer can be suppressed             by not providing content for the corresponding             slots.         </p> Here is the footer </p> <pre><code>    &lt;vx-panel&gt;
        &lt;em slot="header"&gt;Demo vx-panel header&lt;/em&gt;
        &lt;p&gt;This is the panel content.&lt;/p&gt;
        &lt;p&gt;
            The header and footer can be suppressed
            by not providing content for the corresponding
            slots.
        &lt;/p&gt;
        &lt;small slot="footer"&gt;Here is the footer&lt;/small&gt;
    &lt;/vx-panel&gt;
</code></pre>

OutputHTML <pre><code>    &lt;div style="display: flex; flex-flow: row wrap; gap: 12px; color: orange; font-size: 3em"&gt;
        &lt;vx-svg library="shapes" name="circle"&gt;&lt;/vx-svg&gt;
        &lt;vx-svg library="shapes" name="square" button&gt;&lt;/vx-svg&gt;
        &lt;vx-svg library="shapes" name="square-fill"&gt;&lt;/vx-svg&gt;
    &lt;/div&gt;
</code></pre>

OutputSource <pre><code>    &lt;script type="module"&gt;
        import {registerSvgLibrary, html} from "/vx-components.js";
        registerSvgLibrary("shapes", {
            "circle" : html`&lt;svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" 
                fill="currentColor" viewBox="0 0 16 16"&gt;
                &lt;path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14m0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16"/&gt;
            &lt;/svg&gt;`,
            "square" : html`&lt;svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" 
                fill="currentColor" viewBox="0 0 16 16"&gt;
                &lt;path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/&gt;
            &lt;/svg&gt;`,
            "square-fill" : html`&lt;svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" 
                fill="currentColor" viewBox="0 0 16 16"&gt;
                &lt;path d="M0 2a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2z"/&gt;
            &lt;/svg&gt;`
        });
    &lt;/script&gt;
    &lt;div style="display: flex; gap: 1rem; font-size:3em; color: orange"&gt;
        &lt;vx-svg library="shapes" name="circle"&gt;&lt;/vx-svg&gt;
        &lt;vx-svg library="shapes" name="square"&gt;&lt;/vx-svg&gt;
        &lt;vx-svg library="shapes" name="square-fill"&gt;&lt;/vx-svg&gt;
    &lt;/div&gt; 
</code></pre>
